-- =============================================================================
-- demo_datos_nl.sql  (NO es parte de la migracion oficial 001-010)
-- Datos SINTETICOS para la demo local: dashboard publico, login, dashboard
-- autenticado y mapa epidemiologico -- alcance Nuevo Leon unicamente.
-- Generado por gen_demo_data.py, seed fija (42), 'hoy' simulado = 2026-09-03.
-- Seguro de volver a correr: trunca antes de insertar.
--
-- Requiere: dump_completo.sql ya aplicado (schema + catalogos + admin).
-- =============================================================================

BEGIN;

-- Reinicio limpio de las tablas que toca esta demo. No toca users/roles reales
-- salvo por el INSERT del usuario de demo mas abajo (ON CONFLICT DO NOTHING).
TRUNCATE case_attachments, cases, scenario_interventions, simulation_runs,
         simulation_batches, scenario_versions, scenarios RESTART IDENTITY CASCADE;

